SELECT p.PartiNo, p.PartiKodu AS [Parti No], Format(p.Tarih,"dd.mm.yyyy") AS Tarih, m.AdSoyad AS Müşteri, Trim(Nz(p.Cinsi,"") & IIf(p.Ozellik Is Null,""," / " & p.Ozellik)) AS [Cinsi / Özellik], p.BrutKg AS [Brüt Kg], p.DaraKg AS [Dara Kg], p.ZeytinMiktari_Kg AS [Net Kg], p.OdemeTipi AS Ödeme, p.BidonDetay AS Bidonlar, IIf(p.TeslimTarihi Is Not Null,"Teslim Edildi",IIf(p.SikimTarihi Is Not Null And Nz(p.CikanYag_Kg,0)>0,"Üretildi","Kabul")) AS Durum, p.Sezon, p.Tarih AS TarihHam, Val(Nz(p.PartiKodu,"0")) AS PartiSira, p.MusteriID
FROM tbl_Parti AS p LEFT JOIN tbl_Musteri AS m ON p.MusteriID=m.MusteriID;